struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn tcgetattr(fd: c_int, termios: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, action: c_int, termios: *const Termios) -> c_int;
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    fn signal(signum: c_int, handler: usize) -> usize;
    fn read(fd: c_int, buf: *mut c_void, count: usize) -> isize;
    fn write(fd: c_int, buf: *const c_void, count: usize) -> isize;
}

const BRKINT: u32 = 0o2;
const ICRNL: u32 = 0o400;
const INPCK: u32 = 0o20;
const ISTRIP: u32 = 0o40;
const IXON: u32 = 0o2000;
const OPOST: u32 = 0o1;
const CS8: u32 = 0o60;
const ISIG: u32 = 0o1;
const ICANON: u32 = 0o2;
const ECHO: u32 = 0o10;
const IEXTEN: u32 = 0o100000;
const VTIME: usize = 5;
const VMIN: usize = 6;
const TCSAFLUSH: c_int = 2;
const TIOCGWINSZ: c_ulong = 0x5413;
const SIGWINCH: c_int = 28;
const EINTR: i32 = 4;
const EAGAIN: i32 = 11;

static mut ORIG_TERMIOS: Option<Termios> = None;
static RESIZED: AtomicBool = AtomicBool::new(false);

extern "C" fn on_sigwinch(_: c_int) {
    RESIZED.store(true, Ordering::SeqCst);
}

/// Enables raw mode on stdin. Returns an error when stdin is not a terminal.
pub fn enable_raw_mode() -> io::Result<()> {
    unsafe {
        let mut t: Termios = std::mem::zeroed();
        if tcgetattr(0, &mut t) != 0 {
            return Err(io::Error::last_os_error());
        }
        ORIG_TERMIOS = Some(t);
        let mut raw = t;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !OPOST;
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN] = 0;
        raw.c_cc[VTIME] = 1;
        if tcsetattr(0, TCSAFLUSH, &raw) != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    Ok(())
}

/// Restores the terminal attributes saved by `enable_raw_mode`.
pub fn disable_raw_mode() {
    unsafe {
        let orig = std::ptr::addr_of!(ORIG_TERMIOS).read();
        if let Some(t) = orig {
            tcsetattr(0, TCSAFLUSH, &t);
            ORIG_TERMIOS = None;
        }
    }
}

pub fn install_sigwinch_handler() {
    unsafe {
        signal(SIGWINCH, on_sigwinch as usize);
    }
}

pub fn take_resized() -> bool {
    RESIZED.swap(false, Ordering::SeqCst)
}

/// Window size obtained with ioctl on stdout. None when unavailable.
pub fn window_size_ioctl() -> Option<(usize, usize)> {
    unsafe {
        let mut ws: Winsize = std::mem::zeroed();
        if ioctl(1, TIOCGWINSZ, &mut ws as *mut Winsize) == -1 || ws.ws_col == 0 {
            None
        } else {
            Some((ws.ws_row as usize, ws.ws_col as usize))
        }
    }
}

/// Reads one byte from stdin. Returns Ok(None) on timeout.
pub fn read_byte() -> io::Result<Option<u8>> {
    let mut b: u8 = 0;
    loop {
        let n = unsafe { read(0, &mut b as *mut u8 as *mut c_void, 1) };
        if n == 1 {
            return Ok(Some(b));
        }
        if n == 0 {
            return Ok(None);
        }
        let err = io::Error::last_os_error();
        match err.raw_os_error() {
            Some(EINTR) => continue,
            Some(EAGAIN) => return Ok(None),
            _ => return Err(err),
        }
    }
}

/// Writes all bytes to stdout without any buffering.
pub fn write_stdout(mut data: &[u8]) -> io::Result<()> {
    while !data.is_empty() {
        let n = unsafe { write(1, data.as_ptr() as *const c_void, data.len()) };
        if n < 0 {
            let err = io::Error::last_os_error();
            if err.raw_os_error() == Some(EINTR) {
                continue;
            }
            return Err(err);
        }
        data = &data[n as usize..];
    }
    Ok(())
}
