//! Error type used across the editor.

use std::fmt;
use std::io;

pub enum Error {
    Io(io::Error),
    Msg(String),
    /// A panic-equivalent failure. The message was already printed to stderr.
    Panicked,
}

pub type Result<T> = std::result::Result<T, Error>;

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Error {
        Error::Io(e)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(e) => write!(f, "{}", e),
            Error::Msg(m) => write!(f, "{}", m),
            Error::Panicked => write!(f, "panicked"),
        }
    }
}

/// Reports a fatal internal error in the same format as Rust's default panic hook
/// and returns an error which makes the program terminate with status 101.
pub fn fatal(location: &str, message: &str) -> Error {
    let text = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        std::process::id(),
        location,
        message
    );
    let _ = io::Write::write_all(&mut io::stderr(), text.as_bytes());
    Error::Panicked
}

/// Slices `s` to `end` bytes, failing like Rust's str slicing when `end` is not on a
/// character boundary.
pub fn slice_to<'a>(s: &'a str, end: usize, location: &str) -> Result<&'a str> {
    if end >= s.len() {
        return Ok(s);
    }
    if s.is_char_boundary(end) {
        return Ok(&s[..end]);
    }
    let mut start = end;
    while !s.is_char_boundary(start) {
        start -= 1;
    }
    let ch = s[start..].chars().next().unwrap();
    let ch_end = start + ch.len_utf8();
    const MAX: usize = 256;
    let (shown, ellipsis) = if s.len() <= MAX {
        (s, "")
    } else {
        let mut t = MAX;
        while !s.is_char_boundary(t) {
            t -= 1;
        }
        (&s[..t], "[...]")
    };
    let msg = format!(
        "byte index {} is not a char boundary; it is inside {:?} (bytes {}..{}) of `{}`{}",
        end, ch, start, ch_end, shown, ellipsis
    );
    Err(fatal(location, &msg))
}
