//! Display width of characters on terminal (East Asian ambiguous characters are wide).

use crate::width_table::WIDTH_TABLE;

/// Returns None for control characters.
pub fn char_width_opt(c: char) -> Option<usize> {
    let cp = c as u32;
    if cp == 0 {
        return Some(0);
    }
    if cp < 0x20 {
        return None;
    }
    if cp < 0x7f {
        return Some(1);
    }
    if cp < 0xa0 {
        return None;
    }
    let mut lo = 0usize;
    let mut hi = WIDTH_TABLE.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (s, e, w) = WIDTH_TABLE[mid];
        if cp < s {
            hi = mid;
        } else if cp > e {
            lo = mid + 1;
        } else {
            return Some(w as usize);
        }
    }
    Some(1)
}

pub fn char_width(c: char) -> usize {
    char_width_opt(c).unwrap_or(0)
}
