    fn read_blocking(&mut self) -> Result<u8> {
        loop {
            if let Some(b) = term::read_byte()? {
                return Ok(b);
            }
        }
    }

    pub fn next_seq(&mut self) -> Result<InputSeq> {
        let b = self.read_blocking()?;
        self.decode(b)
    }

    fn decode(&mut self, b: u8) -> Result<InputSeq> {
        use KeyCode::*;
        match b {
            0x1b => self.decode_escape(),
            0x00..=0x1a => Ok(InputSeq::ctrl(Byte(b | 0x60))),
            0x1c => Ok(InputSeq::ctrl(Byte(b'\\'))),
            0x1d => Ok(InputSeq::ctrl(Byte(b']'))),
            0x1e => Ok(InputSeq::ctrl(Byte(b'^'))),
            0x1f => Ok(InputSeq::ctrl(Byte(b'?'))),
            0x20..=0x7f => Ok(InputSeq::new(Byte(b))),
            _ => self.decode_utf8(b),
        }
    }

    fn decode_utf8(&mut self, b: u8) -> Result<InputSeq> {
        let len = if b & 0b1110_0000 == 0b1100_0000 {
            2
        } else if b & 0b1111_0000 == 0b1110_0000 {
            3
        } else {
            4
        };
        let mut bytes = vec![b];
        for _ in 1..len {
            bytes.push(self.read_blocking()?);
        }
        match std::str::from_utf8(&bytes) {
            Ok(s) => {
                let c = s.chars().next().unwrap();
                Ok(InputSeq::new(KeyCode::Char(c)))
            }
            Err(_) => {
                let mut msg = String::from("Cannot handle non-UTF8 multi-byte input sequence: ");
                for b in bytes.iter() {
                    msg.push_str(&format!("\\x{:x}", b));
                }
                Err(Error::Msg(msg))
            }
        }
    }

    fn decode_escape(&mut self) -> Result<InputSeq> {
        let b = self.read_blocking()?;
        if b == b'[' {
            return self.decode_csi();
        }
        if b.is_ascii_control() {
            // ESC key (Ctrl-[). The following control byte is ignored.
            return Ok(InputSeq::ctrl(KeyCode::Byte(b'[')));
        }
        let mut seq = self.decode(b)?;
        seq.alt = true;
        Ok(seq)
    }

    fn decode_csi(&mut self) -> Result<InputSeq> {
        use KeyCode::*;
        let mut buf = Vec::new();
        let cmd = loop {
            let b = self.read_blocking()?;
            match b {
                b'A' | b'B' | b'C' | b'D' | b'F' | b'H' | b'K' | b'J' | b'R' | b'c' | b'f'
                | b'g' | b'h' | b'l' | b'm' | b'n' | b'q' | b'y' | b'~' => break b,
                _ => buf.push(b),
            }
        };
        let args: Vec<&[u8]> = buf.split(|b| *b == b';').collect();
        match cmd {
            b'R' => {
                let parse = |a: Option<&&[u8]>| -> Option<usize> {
                    a.and_then(|b| std::str::from_utf8(b).ok()).and_then(|s| s.parse::<usize>().ok())
                };
                match (parse(args.first()), parse(args.get(1))) {
                    (Some(r), Some(c)) => Ok(InputSeq::new(Cursor(r, c))),
                    _ => Ok(InputSeq::new(Unidentified)),
                }
            }
            b'~' => {
                let key = match args.first().copied() {
                    Some(b"1") | Some(b"7") => Home,
                    Some(b"4") | Some(b"8") => End,
                    Some(b"3") => Delete,
                    Some(b"5") => PageUp,
                    Some(b"6") => PageDown,
                    _ => Unidentified,
                };
                Ok(InputSeq::new(key))
            }
            b'A' | b'B' | b'C' | b'D' | b'H' | b'F' => {
                let (ctrl, alt) = match (args.first().copied(), args.get(1).copied()) {
                    (Some(b"1"), Some(b"5")) => (true, false),
                    (Some(b"1"), Some(b"3")) => (false, true),
                    _ => (false, false),
                };
                let key = match cmd {
                    b'A' => Up,
                    b'B' => Down,
                    b'C' => Right,
                    b'D' => Left,
                    b'H' => Home,
                    _ => End,
                };
                Ok(InputSeq { key, ctrl, alt })
            }
            _ => Err(fatal("src/input.rs:254:18", "internal error: entered unreachable code")),
        }
    }
}
