//! A line of text and its rendered representation (tabs expanded).

use crate::width::char_width;

pub const TAB_STOP: usize = 8;

#[derive(Clone)]
pub struct Row {
    buf: String,
    render: String,
    nchars: usize,
}

impl Row {
    pub fn new<S: Into<String>>(s: S) -> Row {
        let mut r = Row { buf: s.into(), render: String::new(), nchars: 0 };
        r.update();
        r
    }

    pub fn empty() -> Row {
        Row::new(String::new())
    }

    fn update(&mut self) {
        let mut render = String::with_capacity(self.buf.len());
        let mut col = 0;
        let mut n = 0;
        for c in self.buf.chars() {
            n += 1;
            if c == '\t' {
                loop {
                    render.push(' ');
                    col += 1;
                    if col % TAB_STOP == 0 {
                        break;
                    }
                }
            } else {
                render.push(c);
                col += char_width(c);
            }
        }
        self.render = render;
        self.nchars = n;
    }

    pub fn buffer(&self) -> &str {
        &self.buf
    }

    pub fn render_text(&self) -> &str {
        &self.render
    }

    /// Length in characters
    pub fn len(&self) -> usize {
        self.nchars
    }

    pub fn is_empty(&self) -> bool {
        self.buf.is_empty()
    }

    pub fn char_at(&self, x: usize) -> Option<char> {
        self.buf.chars().nth(x)
    }

    fn byte_idx(&self, x: usize) -> usize {
        match self.buf.char_indices().nth(x) {
            Some((i, _)) => i,
            None => self.buf.len(),
        }
    }

    /// Display column of the character at char index `cx`
    pub fn rx_from_cx(&self, cx: usize) -> usize {
        let mut rx = 0;
        for c in self.buf.chars().take(cx) {
            if c == '\t' {
                rx += TAB_STOP - rx % TAB_STOP;
            } else {
                rx += char_width(c);
            }
        }
        rx
    }

    pub fn insert_char(&mut self, x: usize, c: char) {
        let i = self.byte_idx(x);
        self.buf.insert(i, c);
        self.update();
    }

    pub fn insert_str(&mut self, x: usize, s: &str) {
        let i = self.byte_idx(x);
        self.buf.insert_str(i, s);
        self.update();
    }

    /// Removes the character at char index x and returns it
    pub fn remove_char(&mut self, x: usize) -> char {
        let i = self.byte_idx(x);
        let c = self.buf.remove(i);
        self.update();
        c
    }

    /// Removes chars in [start, end) and returns them
    pub fn remove_range(&mut self, start: usize, end: usize) -> String {
        let s = self.byte_idx(start);
        let e = self.byte_idx(end);
        let removed: String = self.buf[s..e].to_string();
        self.buf.replace_range(s..e, "");
        self.update();
        removed
    }

    /// Truncates at char index x and returns the removed tail
    pub fn truncate(&mut self, x: usize) -> String {
        let i = self.byte_idx(x);
        let tail = self.buf[i..].to_string();
        self.buf.truncate(i);
        self.update();
        tail
    }

    pub fn append(&mut self, s: &str) {
        self.buf.push_str(s);
        self.update();
    }

    pub fn chars_vec(&self) -> Vec<char> {
        self.buf.chars().collect()
    }
}
EOF
