//! Undo/redo history of edits.

#[derive(Clone, Debug)]
pub enum EditDiff {
    /// Character inserted at (x, y)
    InsertChar(usize, usize, char),
    /// Character removed at (x, y)
    DeleteChar(usize, usize, char),
    /// Line inserted at y
    InsertLine(usize, String),
    /// Line y split at x
    Newline(usize, usize),
    /// Line y+1 appended to line y whose length was x
    Join(usize, usize),
    /// Text removed from line y starting at x
    Remove(usize, usize, String),
    /// Line y truncated at x, removing the text
    Truncate(usize, usize, String),
}

pub struct History {
    entries: Vec<Vec<EditDiff>>,
    index: usize,
    ongoing: Vec<EditDiff>,
    saved_index: Option<usize>,
