    }
}

fn at_word_start(left: CharKind, right: CharKind) -> bool {
    use CharKind::*;
    matches!((left, right), (Space, Ident) | (Space, Punc) | (Punc, Ident) | (Ident, Punc))
}

impl TextBuffer {
    pub fn empty() -> TextBuffer {
        TextBuffer {
            rows: vec![Row::empty()],
            cx: 0,
            cy: 0,
            filename: None,
            lang: Language::Plain,
            history: History::new(),
            dirty: None,
            hl: Highlighting::new(Language::Plain),
        }
    }

    pub fn open(path_str: &str) -> Result<TextBuffer> {
        let path = Path::new(path_str);
        let lang = Language::detect(path);
        let rows = if path.exists() {
            let file = File::open(path)?;
            let mut rows = Vec::new();
            for line in BufReader::new(file).lines() {
                let line = line?;
                for c in line.chars() {
                    if c != '\t' && char_width_opt(c).is_none() {
                        return Err(crate::error::Error::Msg(format!(
                            "Invalid character for text is included: {:?}",
                            c
                        )));
                    }
                }
                rows.push(Row::new(line));
            }
            rows
        } else {
            vec![Row::empty()]
        };
        Ok(TextBuffer {
            rows,
            cx: 0,
            cy: 0,
            filename: Some(path_str.to_string()),
            lang,
            history: History::new(),
            dirty: None,
            hl: Highlighting::new(lang),
        })
    }

    pub fn modified(&self) -> bool {
        self.history.modified()
    }

    pub fn display_name(&self) -> &str {
        match &self.filename {
            Some(f) => f,
            None => "[No Name]",
        }
    }

    fn set_dirty(&mut self, y: usize) {
        self.dirty = Some(match self.dirty {
            Some(d) if d < y => d,
            _ => y,
        });
        self.hl.invalidate(y);
    }

    pub fn take_dirty(&mut self) -> Option<usize> {
        self.dirty.take()
    }

    // ---- file ----

    pub fn save(&mut self) -> io::Result<usize> {
        let name = self.filename.clone().unwrap_or_default();
        let mut f = File::create(&name)?;
        let mut bytes = 0;
        let mut data = Vec::new();
        for row in self.rows.iter() {
            data.extend_from_slice(row.buffer().as_bytes());
            data.push(b'\n');
            bytes += row.buffer().len() + 1;
        }
        f.write_all(&data)?;
        f.flush()?;
        self.history.mark_saved();
        Ok(bytes)
    }

    pub fn finish_edit(&mut self) {
        self.history.finish_ongoing();
    }

    // ---- cursor movement ----

    fn row_len(&self, y: usize) -> usize {
        self.rows.get(y).map(|r| r.len()).unwrap_or(0)
    }

    fn clamp_x(&mut self) {
        let len = self.row_len(self.cy);
        if self.cx > len {
            self.cx = len;
        }
    }

    pub fn move_left(&mut self) {
        if self.cx > 0 {
            self.cx -= 1;
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.row_len(self.cy);
        }
    }

    pub fn move_right(&mut self) {
        if self.cy < self.rows.len() {
            if self.cx < self.rows[self.cy].len() {
                self.cx += 1;
            } else {
                self.cy += 1;
                self.cx = 0;
            }
        }
    }

    pub fn move_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            self.clamp_x();
        }
    }

    pub fn move_down(&mut self) {
        if self.cy < self.rows.len() {
            self.cy += 1;
            self.clamp_x();
        }
    }

    pub fn move_home(&mut self) {
        self.cx = 0;
    }

    pub fn move_end(&mut self) {
        if self.cy < self.rows.len() {
            self.cx = self.rows[self.cy].len();
        }
    }

    pub fn move_top(&mut self) {
        self.cy = 0;
        self.clamp_x();
    }

    pub fn move_bottom(&mut self) {
        self.cy = self.rows.len();
        self.clamp_x();
    }

    pub fn page_up(&mut self, rowoff: usize, rows: usize) {
        self.cy = rowoff;
        for _ in 0..rows {
            self.move_up();
        }
        self.clamp_x();
    }

    pub fn page_down(&mut self, rowoff: usize, rows: usize) {
        let target = rowoff + rows - 1;
        self.cy = if target > self.rows.len() { self.rows.len() } else { target };
        for _ in 0..rows {
            self.move_down();
        }
        self.clamp_x();
    }

    fn kind_at(&self, x: usize, y: usize) -> CharKind {
        kind_of(self.rows.get(y).and_then(|r| r.char_at(x)))
    }

    pub fn move_word_right(&mut self) {
        self.move_right();
        let mut prev = self.kind_at(self.cx, self.cy);
        self.move_right();
        let mut cur = self.kind_at(self.cx, self.cy);
        loop {
            if (self.cy == 0 && self.cx == 0) || self.cy == self.rows.len() {
                return;
            }
            if at_word_start(prev, cur) {
                return;
            }
            prev = cur;
            self.move_right();
            cur = self.kind_at(self.cx, self.cy);
        }
    }

    pub fn move_word_left(&mut self) {
        loop {
            let (px, py) = (self.cx, self.cy);
            self.move_left();
            if self.cx == px && self.cy == py {
                return;
            }
            if self.cy == 0 && self.cx == 0 {
                return;
            }
            let left = if self.cx == 0 { CharKind::Space } else { self.kind_at(self.cx - 1, self.cy) };
            let right = self.kind_at(self.cx, self.cy);
            if at_word_start(left, right) {
                return;
            }
        }
    }

    pub fn move_paragraph_down(&mut self) {
        loop {
            self.move_down();
            if self.cy == 0 || self.cy >= self.rows.len() {
                return;
            }
            if self.rows[self.cy - 1].is_empty() && !self.rows[self.cy].is_empty() {
                return;
            }
        }
    }

    pub fn move_paragraph_up(&mut self) {
        loop {
            self.move_up();
            if self.cy == 0 || self.cy >= self.rows.len() {
                return;
            }
            if self.rows[self.cy - 1].is_empty() && !self.rows[self.cy].is_empty() {
                return;
            }
        }
    }

    // ---- edits ----

    pub fn insert_char(&mut self, c: char) {
        if self.cy == self.rows.len() {
            self.rows.push(Row::empty());
            self.history.push(EditDiff::InsertLine(self.cy, String::new()));
        }
        self.rows[self.cy].insert_char(self.cx, c);
        self.history.push(EditDiff::InsertChar(self.cx, self.cy, c));
        self.cx += 1;
        self.set_dirty(self.cy);
    }

    pub fn insert_newline(&mut self) {
        self.history.finish_ongoing();
        let y = self.cy;
        if y == self.rows.len() {
            self.rows.push(Row::empty());
            self.history.push(EditDiff::InsertLine(y, String::new()));
        } else {
            let tail = self.rows[y].truncate(self.cx);
            self.rows.insert(y + 1, Row::new(tail));
            self.history.push(EditDiff::Newline(self.cx, y));
            self.cy += 1;
            self.cx = 0;
        }
        self.set_dirty(y);
    }

    pub fn delete_char(&mut self) {
        if self.cy == self.rows.len() || (self.cx == 0 && self.cy == 0) {
            return;
        }
        self.history.finish_ongoing();
        let y = self.cy;
        if self.cx > 0 {
            let c = self.rows[y].remove_char(self.cx - 1);
            self.cx -= 1;
            self.history.push(EditDiff::DeleteChar(self.cx, y, c));
            self.set_dirty(y);
        } else {
            let x = self.rows[y - 1].len();
            let row = self.rows.remove(y);
            self.rows[y - 1].append(row.buffer());
            self.history.push(EditDiff::Join(x, y - 1));
            self.cy -= 1;
            self.cx = x;
            self.set_dirty(y - 1);
        }
    }

    pub fn delete_right_char(&mut self) {
        if self.cy == self.rows.len() {
            return;
        }
        let y = self.cy;
        if self.cx < self.rows[y].len() {
            self.history.finish_ongoing();
            let c = self.rows[y].remove_char(self.cx);
            self.history.push(EditDiff::DeleteChar(self.cx, y, c));
            self.set_dirty(y);
        } else if y + 1 < self.rows.len() {
            self.history.finish_ongoing();
            let row = self.rows.remove(y + 1);
            self.rows[y].append(row.buffer());
            self.history.push(EditDiff::Join(self.cx, y));
            self.set_dirty(y);
        }
    }

    pub fn delete_word(&mut self) {
        if self.cy == self.rows.len() || self.cx == 0 {
            return;
        }
        let chars = self.rows[self.cy].chars_vec();
        let mut x = self.cx;
        while x > 0 && chars[x - 1].is_whitespace() {
            x -= 1;
        }
        while x > 0 && !chars[x - 1].is_whitespace() {
            x -= 1;
        }
        if x == self.cx {
            return;
        }
        self.history.finish_ongoing();
        let y = self.cy;
        let removed = self.rows[y].remove_range(x, self.cx);
        self.history.push(EditDiff::Remove(x, y, removed));
        self.cx = x;
        self.set_dirty(y);
    }

    pub fn delete_until_head(&mut self) {
        if self.cy == self.rows.len() || self.cx == 0 {
            return;
        }
        self.history.finish_ongoing();
        let y = self.cy;
        let removed = self.rows[y].remove_range(0, self.cx);
        self.history.push(EditDiff::Remove(0, y, removed));
        self.cx = 0;
        self.set_dirty(y);
    }

    pub fn delete_until_end(&mut self) {
        if self.cy == self.rows.len() || self.cx >= self.rows[self.cy].len() {
            return;
        }
        self.history.finish_ongoing();
        let y = self.cy;
        let removed = self.rows[y].truncate(self.cx);
        self.history.push(EditDiff::Truncate(self.cx, y, removed));
        self.set_dirty(y);
    }

    // ---- undo / redo ----

    pub fn undo(&mut self) -> bool {
        let diffs = match self.history.undo() {
            Some(d) => d.clone(),
            None => return false,
        };
        let mut min_y = usize::MAX;
        for diff in diffs.iter().rev() {
            match diff {
                EditDiff::InsertChar(x, y, _) => {
                    self.rows[*y].remove_char(*x);
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::DeleteChar(x, y, c) => {
                    self.rows[*y].insert_char(*x, *c);
                    self.cx = *x + 1;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::InsertLine(y, _) => {
                    self.rows.remove(*y);
                    self.cx = 0;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Newline(x, y) => {
                    let next = self.rows.remove(*y + 1);
                    self.rows[*y].append(next.buffer());
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Join(x, y) => {
                    let tail = self.rows[*y].truncate(*x);
                    self.rows.insert(*y + 1, Row::new(tail));
                    self.cx = 0;
                    self.cy = *y + 1;
                    min_y = min_y.min(*y);
                }
                EditDiff::Remove(x, y, s) => {
                    self.rows[*y].insert_str(*x, s);
                    self.cx = *x + s.chars().count();
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Truncate(x, y, s) => {
                    self.rows[*y].append(s);
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
            }
        }
        if min_y != usize::MAX {
            self.set_dirty(min_y);
        }
        true
    }

    pub fn redo(&mut self) -> bool {
        let diffs = match self.history.redo() {
            Some(d) => d.clone(),
            None => return false,
        };
        let mut min_y = usize::MAX;
        for diff in diffs.iter() {
            match diff {
                EditDiff::InsertChar(x, y, c) => {
                    self.rows[*y].insert_char(*x, *c);
                    self.cx = *x + 1;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::DeleteChar(x, y, _) => {
                    self.rows[*y].remove_char(*x);
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::InsertLine(y, s) => {
                    self.rows.insert(*y, Row::new(s.clone()));
                    self.cx = 0;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Newline(x, y) => {
                    let tail = self.rows[*y].truncate(*x);
                    self.rows.insert(*y + 1, Row::new(tail));
                    self.cx = 0;
                    self.cy = *y + 1;
                    min_y = min_y.min(*y);
                }
                EditDiff::Join(x, y) => {
                    let next = self.rows.remove(*y + 1);
                    self.rows[*y].append(next.buffer());
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Remove(x, y, s) => {
                    let n = s.chars().count();
                    self.rows[*y].remove_range(*x, *x + n);
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
                EditDiff::Truncate(x, y, _) => {
                    self.rows[*y].truncate(*x);
                    self.cx = *x;
                    self.cy = *y;
                    min_y = min_y.min(*y);
                }
            }
        }
        if min_y != usize::MAX {
            self.set_dirty(min_y);
        }
        true
    }
}
