use std::io::Write;
use std::time::Instant;

pub const VERSION: &str = "0.4.3";

pub struct Message {
    pub text: String,
    pub error: bool,
    pub at: Instant,
}

pub const HELP: &[(&str, &str)] = &[
    ("Ctrl-Q", "Quit"),
