    ("Alt-F or Ctrl-RIGHT", "Move cursor to next word"),
    ("Alt-B or Ctrl-LEFT", "Move cursor to previous word"),
    ("Alt-N or Ctrl-DOWN", "Move cursor to next paragraph"),
    ("Alt-P or Ctrl-UP", "Move cursor to previous paragraph"),
    ("Alt-<", "Move cursor to top of file"),
    ("Alt->", "Move cursor to bottom of file"),
    ("Ctrl-H or BACKSPACE", "Delete character"),
    ("Ctrl-D or DELETE", "Delete next character"),
    ("Ctrl-W", "Delete a word"),
    ("Ctrl-J", "Delete until head of line"),
    ("Ctrl-K", "Delete until end of line"),
    ("Ctrl-U", "Undo last change"),
    ("Ctrl-R", "Redo last undo change"),
    ("Ctrl-G", "Search text"),
    ("Ctrl-M", "New line"),
    ("Ctrl-L", "Refresh screen"),
    ("Ctrl-?", "Show this help"),
];

pub struct StatusInfo {
    pub buf_index: usize,
    pub buf_count: usize,
}

pub struct Screen {
    /// Pending output (flushed at the end of each render)
    pub out: Vec<u8>,
    pub num_rows: usize,
    pub num_cols: usize,
    pub rowoff: usize,
    pub coloff: usize,
    rx: usize,
    color: TermColor,
    message: Option<Message>,
    message_changed: bool,
    msg_shown: bool,
    dirty_start: Option<usize>,
    last_status: Option<String>,
    force_status: bool,
    last_cursor: Option<(usize, usize)>,
}

impl Screen {
    pub fn new(num_rows: usize, num_cols: usize, color: TermColor) -> Screen {
        let mut s = Screen {
            out: Vec::with_capacity(8192),
            num_rows,
            num_cols,
            rowoff: 0,
            coloff: 0,
            rx: 0,
            color,
            message: None,
            message_changed: false,
            msg_shown: false,
            dirty_start: Some(0),
            last_status: None,
            force_status: false,
            last_cursor: None,
        };
        s.out.extend_from_slice(b"\x1b[?1049h");
        s
    }

    pub fn flush(&mut self) -> Result<()> {
        if !self.out.is_empty() {
            let data = std::mem::take(&mut self.out);
            term::write_stdout(&data)?;
        }
        Ok(())
    }

    pub fn finish(&mut self) {
        let _ = self.flush();
        let _ = term::write_stdout(b"\x1b[?1049l\x1b[H");
    }

    pub fn rows(&self) -> usize {
        let reserved = if self.message.is_some() { 2 } else { 1 };
        self.num_rows.saturating_sub(reserved)
    }

    pub fn set_dirty(&mut self, y: usize) {
        self.dirty_start = Some(match self.dirty_start {
            Some(d) if d < y => d,
            _ => y,
        });
    }

    pub fn force_status(&mut self) {
        self.force_status = true;
    }

    pub fn set_info_message<S: Into<String>>(&mut self, s: S) {
        self.message = Some(Message { text: s.into(), error: false, at: Instant::now() });
        self.message_changed = true;
    }

    pub fn set_error_message<S: Into<String>>(&mut self, s: S) {
        self.message = Some(Message { text: s.into(), error: true, at: Instant::now() });
        self.message_changed = true;
    }

    pub fn unset_message(&mut self) {
        if self.message.is_some() {
            self.message = None;
            self.message_changed = true;
        }
    }

    pub fn resize(&mut self, rows: usize, cols: usize) {
        self.num_rows = rows;
        self.num_cols = cols;
        self.message = None;
        self.msg_shown = false;
        self.message_changed = false;
        self.dirty_start = Some(0);
        self.force_status = true;
    }

    pub fn refresh(&mut self) {
        self.unset_message();
        self.set_dirty(0);
        self.force_status = true;
    }

    fn expire_message(&mut self) {
        if let Some(m) = &self.message {
            if m.at.elapsed().as_secs() > 5 {
                self.message = None;
                self.message_changed = true;
            }
        }
    }

    fn reset(&self) -> &'static [u8] {
        self.color.sequence(Color::Reset)
    }

    /// Adjusts rowoff/coloff so that the cursor is visible. Returns true when scrolled.
    fn do_scroll(&mut self, buf: &TextBuffer) -> bool {
        let prev = (self.rowoff, self.coloff);
        let (cx, cy) = (buf.cx, buf.cy);
        self.rx = if cy < buf.rows.len() { buf.rows[cy].rx_from_cx(cx) } else { 0 };
        let rows = self.rows();
        if cy < self.rowoff {
            self.rowoff = cy;
        }
        if rows > 0 && cy >= self.rowoff + rows {
            self.rowoff = cy - rows + 1;
        }
        if self.rx < self.coloff {
            self.coloff = self.rx;
        }
        if self.num_cols > 0 && self.rx >= self.coloff + self.num_cols {
            // Scroll to the first character boundary which makes the cursor visible
            let need = self.rx + 1 - self.num_cols;
            let mut col = 0;
            let mut found = self.rx;
            if cy < buf.rows.len() {
                for c in buf.rows[cy].render_text().chars() {
                    if col >= need {
                        found = col;
                        break;
                    }
                    col += char_width(c);
                }
                if col >= need && found == self.rx && col <= self.rx {
                    found = col.max(need).min(self.rx);
                    if col >= need {
                        found = col;
                    }
                }
            }
            self.coloff = found;
        }
        prev != (self.rowoff, self.coloff)
    }

    fn cursor_pos(&self, buf: &TextBuffer) -> (usize, usize) {
        (buf.cy - self.rowoff + 1, self.rx - self.coloff + 1)
    }

    fn status_text(&self, buf: &TextBuffer, info: &StatusInfo) -> Result<String> {
        let modified = if buf.modified() { "(modified)" } else { "" };
        let left = format!("{:?} - {}/{} {}", buf.display_name(), info.buf_index, info.buf_count, modified);
        let right = format!("{} {}/{}", buf.lang.name(), buf.cy + 1, buf.rows.len());
        let w = self.num_cols;
        let mut s = String::with_capacity(w);
        if left.len() + right.len() < w {
            s.push_str(&left);
            for _ in 0..(w - left.len() - right.len()) {
                s.push(' ');
            }
            s.push_str(&right);
        } else if left.len() <= w {
            s.push_str(&left);
            for _ in 0..(w - left.len()) {
                s.push(' ');
            }
        } else {
            s.push_str(slice_to(&left, w, "/workspace/src/screen.rs:209:25")?);
        }
        Ok(s)
    }

    fn draw_status_bar(&self, frame: &mut Vec<u8>, status: &str) {
        let _ = write!(frame, "\x1b[{}H", self.rows() + 1);
        frame.extend_from_slice(self.color.sequence(Color::Invert));
        frame.extend_from_slice(status.as_bytes());
        frame.extend_from_slice(self.reset());
    }

    fn draw_message_bar(&self, frame: &mut Vec<u8>) -> Result<()> {
        if let Some(m) = &self.message {
            let _ = write!(frame, "\x1b[{}H", self.num_rows);
            let text = slice_to(&m.text, self.num_cols, "/workspace/src/screen.rs:238:33")?;
            if m.error {
                frame.extend_from_slice(self.color.sequence(Color::RedBg));
                frame.extend_from_slice(text.as_bytes());
                frame.extend_from_slice(self.reset());
            } else {
                frame.extend_from_slice(text.as_bytes());
            }
            frame.extend_from_slice(b"\x1b[K");
        }
        Ok(())
    }

    fn draw_rows(&self, frame: &mut Vec<u8>, dirty: usize, buf: &TextBuffer) {
        frame.extend_from_slice(self.reset());
        let rows = self.rows();
        for y in 0..rows {
            let file_row = y + self.rowoff;
            if file_row < dirty {
                continue;
            }
            let _ = write!(frame, "\x1b[{}H", y + 1);
            if file_row >= buf.rows.len() {
                frame.extend_from_slice(self.color.sequence(Color::NonText));
                frame.push(b'~');
            } else {
                self.draw_row(frame, buf, file_row);
            }
            frame.extend_from_slice(self.reset());
            frame.extend_from_slice(b"\x1b[K");
        }
    }

    fn draw_row(&self, frame: &mut Vec<u8>, buf: &TextBuffer, y: usize) {
        let row = &buf.rows[y];
        let text = row.render_text();
        let nchars = text.chars().count();
        let hl = buf.hl.row_highlight(y, nchars);
        let mut col = 0;
        let mut prev = Highlight::Normal;
        let mut tmp = [0u8; 4];
        for (i, c) in text.chars().enumerate() {
            col += char_width(c);
            if col <= self.coloff {
                continue;
            }
            if col - self.coloff > self.num_cols {
                break;
            }
            let h = hl[i];
            if h != prev {
                if prev.color().has_bg() {
                    frame.extend_from_slice(self.reset());
                }
                frame.extend_from_slice(self.color.sequence(h.color()));
                prev = h;
            }
            frame.extend_from_slice(c.encode_utf8(&mut tmp).as_bytes());
        }
    }

    /// The first rendering when no file is opened
    pub fn render_welcome(&mut self, buf: &TextBuffer, info: &StatusInfo) -> Result<()> {
        self.expire_message();
        self.msg_shown = self.message.is_some();
        self.message_changed = false;
        let status = self.status_text(buf, info)?;
        self.out.extend_from_slice(b"\x1b[?25l");
        let mut frame = Vec::new();
        frame.extend_from_slice(self.reset());
        let rows = self.rows();
        for y in 0..rows {
            let _ = write!(frame, "\x1b[{}H", y + 1);
            frame.extend_from_slice(self.color.sequence(Color::NonText));
            frame.push(b'~');
            if y == rows / 3 {
                let msg = format!("Kiro editor -- version {}", VERSION);
                let msg_len = msg.len().min(self.num_cols);
                let padding = (self.num_cols - msg_len) / 2;
                if padding > 0 {
                    frame.extend_from_slice(self.reset());
                    for _ in 0..padding - 1 {
                        frame.push(b' ');
                    }
                    frame.extend_from_slice(msg[..msg_len].as_bytes());
                } else {
                    // No room for '~'
                    let n = frame.len();
                    frame.truncate(n - 1 - self.color.sequence(Color::NonText).len());
                    frame.extend_from_slice(msg[..msg_len].as_bytes());
                }
            }
            frame.extend_from_slice(b"\x1b[K");
        }
        frame.extend_from_slice(self.reset());
        self.draw_status_bar(&mut frame, &status);
        self.draw_message_bar(&mut frame)?;
        frame.extend_from_slice(b"\x1b[H\x1b[?25h");
        self.out.extend_from_slice(&frame);
        self.flush()?;
        self.last_status = Some(status);
        self.last_cursor = Some((1, 1));
        Ok(())
    }

    /// Render in normal (editing) mode
    pub fn render(&mut self, buf: &mut TextBuffer, info: &StatusInfo) -> Result<()> {
        self.expire_message();
        let mut draw_status = self.force_status;
        let mut draw_msg = false;
        let shown = self.message.is_some();
        if shown != self.msg_shown {
            draw_status = true;
            if shown {
                draw_msg = true;
            } else {
                let y = self.rowoff + self.rows() - 1;
                self.set_dirty(y);
            }
            self.msg_shown = shown;
        } else if shown && self.message_changed {
            draw_msg = true;
        }
        self.message_changed = false;

        if self.do_scroll(buf) {
            let r = self.rowoff;
            self.set_dirty(r);
        }
        if let Some(d) = buf.take_dirty() {
