            }
            frame.extend_from_slice(b"\x1b[K");
        }
        Ok(())
    }

    fn draw_rows(&self, frame: &mut Vec<u8>, dirty: usize, buf: &TextBuffer) {
        frame.extend_from_slice(self.reset());
        let rows = self.rows();
        for y in 0..rows {
            let file_row = y + self.rowoff;
            if file_row < dirty {
                continue;
            }
            let _ = write!(frame, "\x1b[{}H", y + 1);
            if file_row >= buf.rows.len() {
