    Search,
}

enum PromptResult {
    Canceled,
    Input(String),
}

pub struct Editor {
    input: Input,
    screen: Screen,
    bufs: Vec<TextBuffer>,
    idx: usize,
    quitting: bool,
    welcome: bool,
}

struct SearchState {
    saved: (usize, usize, usize, usize),
    current: Option<(usize, usize)>,
}

fn char_to_byte(s: &str, x: usize) -> usize {
    match s.char_indices().nth(x) {
        Some((i, _)) => i,
        None => s.len(),
    }
