use error::Error;
use std::env;
use std::io::Write;
use std::process::exit;

enum ArgError {
    Unrecognized(String),
    UnexpectedArgument(String),
    Duplicated(String),
}

impl ArgError {
    fn message(&self) -> String {
        match self {
            ArgError::Unrecognized(n) => format!("Unrecognized option: '{}'", n),
            ArgError::UnexpectedArgument(n) => format!("Option '{}' does not take an argument", n),
            ArgError::Duplicated(n) => format!("Option '{}' given more than once", n),
        }
    }
}

struct Opts {
    version: bool,
    help: bool,
    files: Vec<String>,
}

fn parse_args(args: &[String]) -> Result<Opts, ArgError> {
    let mut version = 0;
    let mut help = 0;
    let mut files = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if arg == "--" {
            files.extend(args[i..].iter().cloned());
            break;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, value) = match long.find('=') {
                Some(p) => (&long[..p], Some(&long[p + 1..])),
                None => (long, None),
            };
            match name {
                "version" | "help" => {
                    if value.is_some() {
                        return Err(ArgError::UnexpectedArgument(name.to_string()));
                    }
                    if name == "version" {
                        version += 1;
                    } else {
                        help += 1;
                    }
                }
                _ => return Err(ArgError::Unrecognized(name.to_string())),
            }
        } else if arg.len() > 1 && arg.starts_with('-') {
            for c in arg[1..].chars() {
                match c {
                    'v' => version += 1,
                    'h' => help += 1,
                    _ => return Err(ArgError::Unrecognized(c.to_string())),
                }
            }
        } else {
            files.push(arg.clone());
        }
    }
    if version > 1 {
        return Err(ArgError::Duplicated("version".to_string()));
    }
    if help > 1 {
        return Err(ArgError::Duplicated("help".to_string()));
    }
    Ok(Opts { version: version > 0, help: help > 0, files })
}

fn usage(program: &str) -> String {
    let mut s = format!(
        "{}: A tiny UTF-8 terminal text editor\n\n\
         Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.\n\
         Specify file paths to edit as a command argument or run without argument to\n\
         start to write a new text.\n\
         Help can show up with key mapping Ctrl-?.\n\n\
         Usage:\n    {} [options] [FILES...]\n\n\
         Mappings:\n",
        program, program
    );
    for (key, desc) in screen::HELP.iter() {
        s.push_str(&format!("    {:<30}: {}\n", key, desc));
    }
    s.push_str("\nOptions:\n");
    s.push_str("    -v, --version       Print version\n");
    s.push_str("    -h, --help          Print this help\n");
    s
}

fn window_size(input: &mut input::Input) -> error::Result<(usize, usize)> {
    if let Some(s) = term::window_size_ioctl() {
        return Ok(s);
    }
    term::write_stdout(b"\x1b[9999C\x1b[9999B\x1b[6n")?;
    loop {
        let seq = input.next_seq()?;
        if let input::KeyCode::Cursor(r, c) = seq.key {
            return Ok((r, c));
        }
    }
}

/// Runs the editor. Returns the exit status.
fn run(files: Vec<String>) -> i32 {
    if let Err(e) = term::enable_raw_mode() {
        let _ = writeln!(std::io::stderr(), "Error: {}", e);
        return 1;
    }
    term::install_sigwinch_handler();
    let mut inp = input::Input::new();
    let size = match window_size(&mut inp) {
        Ok(s) => s,
        Err(e) => {
            term::disable_raw_mode();
            return report(e);
        }
    };
    let color = color::TermColor::from_env();
    let screen = screen::Screen::new(size.0, size.1, color);
    let result = match editor::Editor::new(inp, screen, &files) {
        Ok(mut ed) => {
            let r = ed.edit();
            ed.screen_mut().finish();
            r
        }
        Err(e) => {
            // Screen was moved into the failed constructor; emulate its cleanup
            let _ = term::write_stdout(b"\x1b[?1049h\x1b[?1049l\x1b[H");
            Err(e)
        }
    };
    term::disable_raw_mode();
    match result {
        Ok(()) => 0,
        Err(e) => report(e),
    }
}

fn report(e: Error) -> i32 {
    match e {
        Error::Panicked => 101,
        e => {
            let _ = writeln!(std::io::stderr(), "Error: {}", e);
            1
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let program = args.first().cloned().unwrap_or_default();
    let opts = match parse_args(&args[1..]) {
        Ok(o) => o,
        Err(e) => {
            let _ = writeln!(std::io::stderr(), "Error: {}. Please see --help for more details", e.message());
            exit(1);
        }
    };
    if opts.version {
        println!("{}", screen::VERSION);
        return;
    }
    if opts.help {
        println!("{}", usage(&program));
        return;
    }
    exit(run(opts.files));
}
